function detectLang(): string {
  const saved = localStorage.getItem("mander_lang");
  if (saved && LANGS[saved]) return saved;
  return "en";
}

function tl(lang: string, key: string): string {
  return LANGS[lang]?.[key] ?? LANGS.en?.[key] ?? key;
}

