// Weighted random: picks a random item where w = relative probability weight
function _wRand<T>(tiers: {pool: T[]; w: number}[]): T {
  const total = tiers.reduce((s,t) => s + t.w, 0);
  let r = Math.random() * total;
  for (const tier of tiers) { r -= tier.w; if (r <= 0) return tier.pool[Math.floor(Math.random()*tier.pool.length)]; }
  const last = tiers[tiers.length-1]; return last.pool[Math.floor(Math.random()*last.pool.length)];
}

