function makeFakeWin(ts?: string): LiveWin {
  const g = ORIGINALS_FEED[Math.floor(Math.random()*ORIGINALS_FEED.length)];
  const user = _INIT_USERS_POOL[Math.floor(Math.random()*_INIT_USERS_POOL.length)];
  const betUsd = _wRand(_BET_TIERS);
  const isWin = Math.random() < 0.62; // 62% wins, 38% losses
  if (!isWin) {
    return { user, game: g.game, betUsd, win: false, profitUsd: 0, createdAt: ts ?? new Date().toISOString() };
  }
  const multTiers = _GAME_MULT_TIERS[g.game] ?? _GAME_MULT_TIERS["Dice"];
  const mult = _wRand(multTiers);
  const profitUsd = parseFloat((betUsd * (mult - 1)).toFixed(2));
  return { user, game: g.game, betUsd, win: true, profitUsd: Math.max(profitUsd, 0.01), createdAt: ts ?? new Date().toISOString() };
}

function makeFakeWins(count: number): LiveWin[] {
  return Array.from({length:count}, (_,i)=>makeFakeWin(new Date(Date.now()-i*15000).toISOString()));
}
// Keep best wins permanently — replaces the weakest entry once full
function mergeIntoPinned(prev: LiveWin[], win: LiveWin, maxSize = 60): LiveWin[] {
  if (!win.win || win.profitUsd <= 0) return prev;
  const key = `${win.createdAt}_${win.user}`;
  if (prev.some(w => `${w.createdAt}_${w.user}` === key)) return prev;
  if (prev.length < maxSize) return [win, ...prev];
  const minIdx = prev.reduce((mi, w, i) => w.profitUsd < prev[mi].profitUsd ? i : mi, 0);
  if (win.profitUsd > prev[minIdx].profitUsd) {
    const next = [...prev]; next[minIdx] = win; return next;
  }
  return prev;
}

