function nextDisplayId(type: "deposit"|"withdraw"): number {
  const counter = TX_COUNTER[type];
  const current = Math.max(
    parseInt(localStorage.getItem(counter.key) || String(counter.start - 1), 10),
    ...counter.legacyKeys
      .map(key => parseInt(localStorage.getItem(key) || "0", 10))
      .filter(n => Number.isFinite(n) && (type === "deposit" || n < TX_COUNTER.deposit.start)),
  );
  const next = current + 1;
  localStorage.setItem(counter.key, String(next));
  return next;
}
/** Longitud mínima de dirección válida según la red.
 *  BEP20/ERC20 usan formato 0x... (42 chars); TRC20 empieza con T (34 chars). */
function minAddrLen(network: string): number {
  if (["BEP20","ERC20","Arbitrum","Optimism"].includes(network)) return 42;
  if (network === "TRC20") return 34;
  if (["SOL","Solana"].includes(network)) return 32;
  return 26; // BTC, LTC, TRX, etc.
}

