// Estimated total fall duration in ms for a ball with `rows` rows
function plinkoBallFallMs(rows: number): number {
  // timeScale=0.45 on original physics → ~2.2× slower: 8 rows ≈ 4.4 s, 16 rows ≈ 7.1 s
  return 1800 + rows * 335;
}

