  function playChatSound() {
    try {
      const ctx = new AudioContext();
      const gain = ctx.createGain();
      gain.connect(ctx.destination);
      gain.gain.setValueAtTime(0, ctx.currentTime);
      gain.gain.linearRampToValueAtTime(0.18, ctx.currentTime + 0.01);
      gain.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + 0.5);
      const osc1 = ctx.createOscillator();
      osc1.type = "sine";
      osc1.frequency.setValueAtTime(880, ctx.currentTime);
      osc1.frequency.exponentialRampToValueAtTime(1100, ctx.currentTime + 0.08);
      osc1.connect(gain);
      osc1.start(ctx.currentTime);
      osc1.stop(ctx.currentTime + 0.5);
      const osc2 = ctx.createOscillator();
      osc2.type = "sine";
      osc2.frequency.setValueAtTime(1320, ctx.currentTime + 0.07);
      osc2.frequency.exponentialRampToValueAtTime(1480, ctx.currentTime + 0.15);
      const gain2 = ctx.createGain();
      gain2.connect(ctx.destination);
      gain2.gain.setValueAtTime(0, ctx.currentTime + 0.07);
      gain2.gain.linearRampToValueAtTime(0.12, ctx.currentTime + 0.1);
      gain2.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + 0.5);
      osc2.connect(gain2);
      osc2.start(ctx.currentTime + 0.07);
      osc2.stop(ctx.currentTime + 0.5);
    } catch {}
  }

  function loadChatSessions(username: string) {
    try {
      const raw = localStorage.getItem(`chat_sessions_${username}`);
      setChatSessions(raw ? JSON.parse(raw) : []);
    } catch { setChatSessions([]); }
  }

  function saveChatSession(username: string, messages: {role:"user"|"assistant";content:string;isOp?:boolean;opName?:string}[]) {
    if (!username || messages.filter(m=>m.role==="user").length === 0) return;
    try {
      const raw = localStorage.getItem(`chat_sessions_${username}`);
      const sessions = raw ? JSON.parse(raw) : [];
      const ticketId = Math.floor(10000000 + Math.random() * 90000000);
      const agentName = messages.find(m => m.isOp && m.opName)?.opName ?? undefined;
      sessions.unshift({ id: Date.now(), date: new Date().toISOString(), ticketId, agentName, messages });
      localStorage.setItem(`chat_sessions_${username}`, JSON.stringify(sessions.slice(0, 10)));
      setChatSessions(sessions.slice(0, 10));
    } catch {}
  }

  async function checkTicketStatus(username: string) {
    try {
      const r = await fetch(`/api/support-chat/status/${encodeURIComponent(username)}`);
      if (r.ok) {
        const d = await r.json();
        setChatHasOpenTicket(d.has_open_ticket);
        if (d.has_open_ticket && d.chat_id) {
          setChatId(d.chat_id);
          chatIdRef.current = d.chat_id;
        }
        return d;
      }
    } catch {}
    return { has_open_ticket: false, chat_id: null };
  }

  async function loadAllTickets(username: string) {
    try {
      const r = await fetch(`/api/support-chat/tickets/${encodeURIComponent(username)}`);
      if (r.ok) {
        const data: {chat_id:string; status:string; created_at:string}[] = await r.json();
        setAllTickets(data);
      }
    } catch {}
  }

  async function loadTicketMessages(cid: string) {
    try {
      const r = await fetch(`/api/support-chat/${encodeURIComponent(cid)}/messages`);
      if (r.ok) {
        const msgs: any[] = await r.json();
        // Bot replies are saved with sender "assistant". Status notifications (escalation 🔴, op join 🔵/🔒)
        // are also saved as "assistant" but start with a status emoji — style those differently.
        const systemNotifPrefixes = ["🔴", "🔵", "🔒"];
        const isSystemMsg = (m: any) =>
          ((m.sender === "system" || m.sender === "assistant") && systemNotifPrefixes.some(p => m.message?.startsWith(p))) ||
          (m.sender === "admin" && ["🔵", "🔒"].some(p => m.message?.startsWith(p)));
        function parseOpMsg(raw: string): { text: string; opName: string } {
          const match = raw.match(/^([\s\S]*?)\n---MANDER_OP:(.+)---$/);
          if (match) return { text: match[1], opName: match[2] };
          return { text: raw.replace(/^🧑‍💼 Soporte: /, ""), opName: "Support" };
        }
        const converted = msgs
          .filter((m: any) => m.message?.trim())
          .map((m: any) => {
            const sentAt: string = m.created_at ?? new Date().toISOString();
            if (isSystemMsg(m)) return { role: "assistant" as const, content: m.message, system: true, sentAt };
            if (m.sender === "admin") {
              const { text, opName } = parseOpMsg(m.message);
              return { role: "assistant" as const, content: text, isOp: true, opName, sentAt };
            }
            return { role: m.sender === "user" ? "user" as const : "assistant" as const, content: m.message, sentAt };
          });
        if (converted.length > 0) {
          setChatMessages(converted);
        } else {
          setChatMessages([{ role: "assistant" as const, content: `Welcome to Manderbet Casino, how can we help you today? 👋`, sentAt: new Date().toISOString() }]);
        }
        if (msgs.length > 0) chatPollSinceRef.current = msgs[msgs.length - 1].created_at;
      }
    } catch {}
  }

