  async function openChatWidget(uname?: string) {
    const u = uname || chatAuthUser || currentUser;
    setChatOpen(true);
    setChatScreen("lobby"); // Siempre abre en la lista de tickets, nunca auto-navega al chat
    const existingCid = chatIdRef.current;
    if (existingCid && (chatVerified || u)) {
      // Solo carga los datos del ticket sin navegar al chat automáticamente
      await loadTicketMessages(existingCid);
      setChatVerified(true);
      if (u) { setChatAuthUser(u); loadChatSessions(u); loadAllTickets(u); }
      setChatIsClosed(false);
      return;
    }
    if (u) {
      loadChatSessions(u);
      loadAllTickets(u);
      const result = await checkTicketStatus(u);
      if (result?.has_open_ticket && result?.chat_id) {
        await loadTicketMessages(result.chat_id);
        setChatVerified(true);
        setChatAuthUser(u);
        setChatIsClosed(false);
        // No se llama goChat() — el usuario hace clic manualmente en el ticket de la lista
      }
    }
  }

  function closeChat(username?: string) {
    const u = username || chatAuthUser;
    setChatMessages(prev => {
      saveChatSession(u, prev.filter(m=>!m.system));
      return [];
    });
    setChatVerified(false);
    setChatInput("");
    setChatEmojiOpen(false);
    setChatPendingFile(null);
    setChatId(null);
    chatIdRef.current = null;
    setChatIsClosed(false);
    goLobby();
  }

  function handleChatFile(e: React.ChangeEvent<HTMLInputElement>) {
    const file = e.target.files?.[0];
    if (!file) return;
    const kb = file.size / 1024;
    const size = kb < 1024 ? `${kb.toFixed(0)} KB` : `${(kb/1024).toFixed(1)} MB`;
    const previewUrl = file.type.startsWith("image/") ? URL.createObjectURL(file) : null;
    // Revoke previous preview URL to avoid memory leaks
    setChatPendingFile(prev => { if (prev?.previewUrl) URL.revokeObjectURL(prev.previewUrl); return null; });
    setChatPendingFile({ name: file.name, size, file, previewUrl });
    e.target.value = "";
  }

  async function sendFileMessage() {
    if (!chatPendingFile || chatFileUploading || chatIsClosed) return;
    const { file } = chatPendingFile;
    const isImage = file.type.startsWith("image/");
    if (!isImage) {
      // Non-image: send as text annotation
      const msg = `📎 ${chatPendingFile.name} (${chatPendingFile.size})`;
      setChatPendingFile(null);
      setChatInput(prev => prev ? `${prev} ${msg}` : msg);
      return;
    }
    setChatFileUploading(true);
    try {
      // Read file as base64
      const base64 = await new Promise<string>((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(reader.result as string);
        reader.onerror = reject;
        reader.readAsDataURL(file);
      });
      const res = await fetch("/api/support/upload-image", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ imageData: base64, filename: file.name, contentType: file.type }),
      });
      const data = await res.json();
      if (!res.ok || !data.url) throw new Error(data.error || "Upload failed");
      // Send image message directly
      setChatPendingFile(prev => { if (prev?.previewUrl) URL.revokeObjectURL(prev.previewUrl); return null; });
      const sid = chatIdRef.current;
      const uname = chatAuthUser;
      const imgMsg = `[IMAGE:${data.url}]`;
      setChatMessages(prev => [...prev, { role:"user" as const, content: imgMsg }]);
      await fetch("/api/support-chat", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ message: imgMsg, username: uname, chat_id: sid }),
      });
    } catch {
      setChatMessages(prev => [...prev, { role:"assistant" as const, content:"❌ Image upload failed. Please try again." }]);
    } finally {
      setChatFileUploading(false);
    }
  }

  const CHAT_EMOJIS = ["😀","😂","😍","😎","🤔","😅","😭","🥰","😤","🤗","👍","👎","🙏","❤️","🎉","🎲","💰","🏆","😮","😱","🤣","💪","🔥","✅","❌","💯","🎁","🤝","😴","🤑","🎯","🍀","🤞","😏","🤩","🥳","🎰","💎","🃏","🎴"];


  async function verifyChatUser() {
    const name = chatAuthInput.trim();
    if (!name) return setChatAuthError("Enter your username");
    if (!ls.get("user_"+name)) return setChatAuthError("User not found");
    setChatAuthUser(name);
    setChatVerified(true);
    setChatAuthError("");
    setChatIsClosed(false);
    loadChatSessions(name);
    chatPollSinceRef.current = new Date().toISOString();
    try {
      const r = await fetch("/api/support-chat/init-session", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ username: name }),
      });
      if (r.ok) {
        const d = await r.json();
        if (d.chat_id) {
          setChatId(d.chat_id);
          chatIdRef.current = d.chat_id;
          setChatHasOpenTicket(d.is_existing === true);
          if (d.is_existing) {
            await loadTicketMessages(d.chat_id);
            goChat();
          } else {
            setChatMessages([{ role:"assistant", content:`Welcome to Manderbet Casino, how can we help you today? 👋`, sentAt: new Date().toISOString() }]);
          }
        } else {
          setChatMessages([{ role:"assistant", content:`Welcome to Manderbet Casino, how can we help you today? 👋`, sentAt: new Date().toISOString() }]);
        }
      } else {
        setChatMessages([{ role:"assistant", content:`Welcome to Manderbet Casino, how can we help you today? 👋` }]);
      }
    } catch {
      setChatMessages([{ role:"assistant", content:`Welcome to Manderbet Casino, how can we help you today? 👋` }]);
    }
  }

  async function sendChatMessage() {
    if (!chatInput.trim() || chatLoading || chatIsClosed) return;
    const userMsg = chatInput.trim();
    setChatInput("");
    setChatMessages(prev => [...prev.filter(m=>!m.transient), { role:"user" as const, content:userMsg, sentAt: new Date().toISOString() }]);
    setChatLoading(true);
    try {
      let sid = chatIdRef.current;
      const uname = chatAuthUser;
      // If no chatId yet, try to init session once more before sending
      if (!sid && uname) {
        try {
          const initRes = await fetch("/api/support-chat/init-session", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ username: uname }),
          });
          if (initRes.ok) {
            const initData = await initRes.json();
            if (initData.chat_id) {
              setChatId(initData.chat_id);
              chatIdRef.current = initData.chat_id;
              sid = initData.chat_id;
              chatPollSinceRef.current = new Date().toISOString();
            }
          }
        } catch {}
      }
      // Check if this is the first user message (to show ticket creation status)
      const isFirstMsg = !chatMessages.some(m => m.role === "user");
      const res = await fetch("/api/support-chat", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ message: userMsg, username: uname, chat_id: sid }),
      });
      const data = await res.json();
      // reply is null when an operator is already in the chat (no bot auto-reply needed)
      if (data.reply) {
        const replyAt = new Date().toISOString();
        const newMsgs: typeof chatMessages = [{ role: "assistant" as const, content: data.reply, sentAt: replyAt }];
        // When escalated, also add the system notification immediately so the poller
        // doesn't need to fetch it (preventing it from appearing a second time)
        if (data.escalated) {
          newMsgs.push({ role: "assistant" as const, content: "🔴 This conversation has been escalated. A human agent will join shortly.", system: true, sentAt: replyAt });
        }
        setChatMessages(prev => [...prev, ...newMsgs]);
        // Advance poll cursor past these already-shown messages so the poller won't re-fetch them
        chatPollSinceRef.current = new Date().toISOString();
      }
    } catch {
      setChatMessages(prev => [...prev, { role:"assistant" as const, content:"Error al conectar. Intentá de nuevo." }]);
    } finally {
      setChatLoading(false);
      playChatSound();
    }
  }

  // Poll for admin replies every 6 seconds
  useEffect(() => {
    if (!chatId || chatScreen !== "chat" || !chatVerified || chatIsClosed) return;
    const id = setInterval(async () => {
      const sid = chatIdRef.current;
      if (!sid) return;
      try {
        const r = await fetch(`/api/support-chat/poll/${sid}?since=${encodeURIComponent(chatPollSinceRef.current)}&_=${Date.now()}`);
        if (!r.ok) return;
        const data = await r.json();
        // Support both old array format and new { messages, ticket_status } format
        const msgs: any[] = Array.isArray(data) ? data : (data.messages ?? []);
        const ticketStatus: string = Array.isArray(data) ? "open" : (data.ticket_status ?? "open");

        // If ticket was closed by admin, update UI immediately
        if (ticketStatus === "closed") {
          setChatIsClosed(true);
          setChatHasOpenTicket(false);
        }

        if (msgs.length > 0) {
          chatPollSinceRef.current = msgs[msgs.length - 1].created_at;
          const systemNotifPrefixesPoll = ["🔴", "🔵", "🔒"];
          const isSystemPollMsg = (m: any) =>
            ((m.sender === "system" || m.sender === "assistant") && systemNotifPrefixesPoll.some(p => m.message?.startsWith(p))) ||
            (m.sender === "admin" && ["🔵", "🔒"].some(p => m.message?.startsWith(p)));
          function parsePollOpMsg(raw: string): { text: string; opName: string } {
            const match = raw.match(/^([\s\S]*?)\n---MANDER_OP:(.+)---$/);
            if (match) return { text: match[1], opName: match[2] };
            return { text: raw.replace(/^🧑‍💼 Soporte: /, ""), opName: "Support" };
          }
          setChatMessages(prev => {
            // Deduplicate: skip messages whose content is already present in the last few
            // messages — prevents duplicates when the poller fires during a bot API call.
            const recentContents = new Set(prev.slice(-10).map(m => m.content));
            const deduped = msgs.filter((m: any) => !recentContents.has(m.message));
            if (deduped.length === 0) return prev;
            return [
              ...prev,
              ...deduped.map((m: any) => {
                const sentAt: string = m.created_at ?? new Date().toISOString();
                if (isSystemPollMsg(m)) return { role: "assistant" as const, content: m.message, system: true, sentAt };
                if (m.sender === "admin") {
                  const { text, opName } = parsePollOpMsg(m.message);
                  return { role: "assistant" as const, content: text, isOp: true, opName, sentAt };
                }
                return { role: "assistant" as const, content: m.message, sentAt };
              }),
            ];
          });
          playChatSound();
        }
      } catch {}
    }, 3000);
    return () => clearInterval(id);
  }, [chatId, chatScreen, chatVerified, chatIsClosed]);
