  function normalizeRewardHistory(records: RewardRecord[]) {
    const sorted = [...records]
      .filter((rec) => Number.isFinite(Number(rec.date)) && Number(rec.amount) > 0)
      .map((rec) => ({ ...rec, date: Number(rec.date), amount: Number(rec.amount) }))
      .sort((a, b) => b.date - a.date);
    const cleaned: RewardRecord[] = [];
    for (const rec of sorted) {
      const duplicateIndex = cleaned.findIndex((existing) =>
        existing.note === rec.note && Math.abs(existing.date - rec.date) <= 2 * 60 * 1000
      );
      if (duplicateIndex >= 0) {
        const existing = cleaned[duplicateIndex];
        if (rec.amount > existing.amount || (Math.abs(rec.amount - existing.amount) < 0.00000001 && rec.date > existing.date)) {
          cleaned[duplicateIndex] = rec;
        }
      } else {
        cleaned.push(rec);
      }
    }
    return cleaned.sort((a, b) => b.date - a.date).slice(0, 500);
  }

  function applyRewardHistory(user: string, records: RewardRecord[]) {
    const cleaned = normalizeRewardHistory(records);
    localStorage.setItem(`rewardHistory_${user}`, JSON.stringify(cleaned));
    setRewardHistory(cleaned);
    return cleaned;
  }

  function isBalanceAdjustmentCredit(tx: Transaction) {
    return tx.type === "admin_adjustment" || (tx.type === "bonus" && String(tx.notes ?? "").includes("[admin_adjustment:credit]"));
  }

  function isBalanceAdjustmentDebit(tx: Transaction) {
    return tx.type === "bonus" && String(tx.notes ?? "").includes("[admin_adjustment:debit]");
  }

  function isDemoBalanceTx(tx: Transaction) {
    return tx.type === "bonus" && String(tx.notes ?? "").includes("[demo_balance]");
  }

  function isDepositLikeTx(tx: Transaction) {
    return tx.type === "deposit" || isBalanceAdjustmentCredit(tx) || isDemoBalanceTx(tx);
  }

  function isWithdrawLikeTx(tx: Transaction) {
    return tx.type === "withdraw" || tx.type === "withdrawal" || isBalanceAdjustmentDebit(tx);
  }

  function getNumericDisplayId(value: unknown) {
    const n = typeof value === "number" ? value : typeof value === "string" && /^\d+$/.test(value.trim()) ? Number(value.trim()) : NaN;
    return Number.isFinite(n) && n > 0 ? Math.trunc(n) : undefined;
  }

  function formatTxDisplayId(value: unknown) {
    const n = getNumericDisplayId(value);
    return n ? `#${String(n).padStart(4, "0")}` : null;
  }

  function shouldHaveDisplayId(tx: Pick<Transaction, "type"> & Partial<Pick<Transaction, "notes">>) {
    const normalizedType = tx.type === "withdrawal" ? "withdraw" : tx.type;
    const normalizedTx = { type: normalizedType, notes: tx.notes } as Transaction;
    return isDepositLikeTx(normalizedTx) || isWithdrawLikeTx(normalizedTx);
  }

  function displayIdKind(tx: Pick<Transaction, "type"> & Partial<Pick<Transaction, "notes">>): "deposit" | "withdraw" {
    const normalizedType = tx.type === "withdrawal" ? "withdraw" : tx.type;
    const normalizedTx = { type: normalizedType, notes: tx.notes } as Transaction;
    return isWithdrawLikeTx(normalizedTx) ? "withdraw" : "deposit";
  }

  function resolveTxDisplayId(
    tx: Pick<Transaction, "type"> & Partial<Pick<Transaction, "id" | "display_id" | "notes">>,
    localTx?: Partial<Pick<Transaction, "display_id">>,
  ) {
    const kind = displayIdKind(tx);
    const cleanForKind = (value: unknown) => {
      const n = getNumericDisplayId(value);
      if (!n) return undefined;
      if (kind === "withdraw" && n >= TX_COUNTER.deposit.start) return undefined;
      return n;
    };
    const remoteId = cleanForKind(tx.display_id);
    const localId = cleanForKind(localTx?.display_id);
    if (remoteId && localId) return Math.max(remoteId, localId);
    return remoteId
      ?? localId
      ?? (shouldHaveDisplayId(tx) ? nextDisplayId(kind) : undefined);
  }

  function syncDisplayCounterFromTransactions(txs: Transaction[]) {
    (["deposit", "withdraw"] as const).forEach(kind => {
      const maxId = txs.reduce((max, tx) => {
        if (!shouldHaveDisplayId(tx) || displayIdKind(tx) !== kind) return max;
        return Math.max(max, getNumericDisplayId(tx.display_id) ?? 0);
      }, 0);
      if (maxId > 0) {
        const current = parseInt(localStorage.getItem(TX_COUNTER[kind].key) || "0", 10);
        if (!Number.isFinite(current) || maxId > current) localStorage.setItem(TX_COUNTER[kind].key, String(maxId));
      }
    });
  }

  function nextSequentialDisplayId(kind: "deposit" | "withdraw", current: number | undefined, last: number) {
    if (kind === "withdraw") return last + 1;
    return current && current > last ? current : last + 1;
  }

  function dedupeTransactionRows(txs: Transaction[]) {
    const seen = new Map<string, Transaction>();
    const deduped: Transaction[] = [];
    const amountKey = (tx: Transaction) => {
      const amount = Math.abs(Number(tx.usdAmount ?? tx.coinAmount ?? tx.amount ?? 0));
      return Number.isFinite(amount) ? amount.toFixed(8) : "0.00000000";
    };
    const betterTx = (existing: Transaction, incoming: Transaction) => {
      const existingLocal = String(existing.id || "").startsWith("local_");
      const incomingLocal = String(incoming.id || "").startsWith("local_");
      if (existingLocal !== incomingLocal) return incomingLocal ? existing : incoming;
      const existingScore = [
        existing.tx_hash,
        existing.notes,
        existing.address,
        existing.network,
      ].filter(Boolean).length;
      const incomingScore = [
        incoming.tx_hash,
        incoming.notes,
        incoming.address,
        incoming.network,
      ].filter(Boolean).length;
      if (incomingScore !== existingScore) return incomingScore > existingScore ? incoming : existing;
      return new Date(incoming.createdAt || 0).getTime() < new Date(existing.createdAt || 0).getTime() ? incoming : existing;
    };
    for (const tx of txs) {
      const displayId = getNumericDisplayId(tx.display_id);
      const key = displayId && isWithdrawLikeTx(tx)
        ? `withdraw:${displayId}:${amountKey(tx)}:${String(tx.coin || "").toUpperCase()}:${String(tx.network || "").toUpperCase()}`
        : null;
      if (!key) {
        deduped.push(tx);
        continue;
      }
      const existing = seen.get(key);
      if (!existing) {
        seen.set(key, tx);
        deduped.push(tx);
        continue;
      }
      const winner = betterTx(existing, tx);
      if (winner !== existing) {
        const index = deduped.indexOf(existing);
        if (index !== -1) deduped[index] = winner;
        seen.set(key, winner);
      }
    }
    return deduped;
  }

  function normalizeTransactionDisplayIds(txs: Transaction[]) {
    const normalized = dedupeTransactionRows(txs).map(tx => {
      const displayId = getNumericDisplayId(tx.display_id);
      return displayId ? { ...tx, display_id: displayId } : tx;
    });
    (["deposit", "withdraw"] as const).forEach(kind => {
      const indexed = normalized
        .map((tx, index) => ({ tx, index }))
        .filter(({ tx }) => shouldHaveDisplayId(tx) && displayIdKind(tx) === kind)
        .sort((a, b) => new Date(a.tx.createdAt || 0).getTime() - new Date(b.tx.createdAt || 0).getTime());
      let last = TX_COUNTER[kind].start - 1;
      for (const { tx, index } of indexed) {
        const current = getNumericDisplayId(tx.display_id);
        const next = nextSequentialDisplayId(kind, current, last);
        normalized[index] = { ...tx, display_id: next };
        last = next;
      }
    });
    syncDisplayCounterFromTransactions(normalized);
    return normalized;
  }

  // Dice state
