  async function claimRankReward() {
    if (!rankPendingReward || !currentUser) return;
    const guardKey = `rank-${rankPendingReward.rankName}`;
    if (claimInFlightRef.current.has(guardKey)) return;
    claimInFlightRef.current.add(guardKey);
    try {
      const tok = supaSessionRef.current?.access_token;
      let skipLocalCredit = false;
      let serverClaimed = false;
      if (tok) {
        const r = await fetch("/api/claim-rank-reward", {
          method: "POST",
          headers: { "Content-Type": "application/json", Authorization: `Bearer ${tok}` },
          body: JSON.stringify({ amount_usd: rankPendingReward.amount, rank_name: rankPendingReward.rankName, currency: "USDT" }),
        });
        if (!r.ok) {
          const data = await r.json().catch(() => ({}));
          const code = (data as any)?.code || (data as any)?.error || "";
          if (code === "already_claimed") {
            // Pop from queue without crediting
            const raw = localStorage.getItem("rank_pending_reward_" + currentUser);
            let queue: typeof rankPendingReward[] = [];
            if (raw) { try { const p = JSON.parse(raw); queue = Array.isArray(p) ? p : [p]; } catch {} }
            queue.shift();
            if (queue.length > 0) {
              localStorage.setItem("rank_pending_reward_" + currentUser, JSON.stringify(queue));
              setRankPendingReward(queue[0]);
            } else {
              localStorage.removeItem("rank_pending_reward_" + currentUser);
              setRankPendingReward(null);
            }
            return;
          }
          // SESSION_NOT_READY means interceptor blocked it — fall through to local credit
          if (code !== "SESSION_NOT_READY") {
            skipLocalCredit = true;
          }
          if (skipLocalCredit) return;
        } else {
          serverClaimed = true;
        }
      }
      const nb = ls.getBalance(currentUser) + rankPendingReward.amount;
      pendingRakebackRef.current += rankPendingReward.amount;
      setCoinBalanceUsd(nb);
      saveRewardClaimAndSync(currentUser, rankPendingReward.amount, `Rank Reward - ${rankPendingReward.rankName}`, !serverClaimed);
      applyRewardHistory(currentUser, getRewardHistory(currentUser));
      const toast = { amount: rankPendingReward.amount, rankName: rankPendingReward.rankName, gradient: rankPendingReward.gradient, color: rankPendingReward.color };
      const raw = localStorage.getItem("rank_pending_reward_" + currentUser);
      let queue: typeof rankPendingReward[] = [];
      if (raw) { try { const p = JSON.parse(raw); queue = Array.isArray(p) ? p : [p]; } catch {} }
      queue.shift();
      if (queue.length > 0) {
        localStorage.setItem("rank_pending_reward_" + currentUser, JSON.stringify(queue));
        setRankPendingReward(queue[0]);
      } else {
        localStorage.removeItem("rank_pending_reward_" + currentUser);
        setRankPendingReward(null);
      }
      setRankCreditToast(toast);
      setTimeout(() => setRankCreditToast(null), 5000);
      fetchRemoteBalanceRef.current(currentUser);
    } catch {
    } finally {
      claimInFlightRef.current.delete(guardKey);
    }
  }

