  // ── Per-coin balance helper ────────────────────────────────────────────────
  // Updates both the USD `balance` state and the native amount in `coinBalances`
  // for the currently selected coin.  All game win/loss handlers should use this.
  function setCoinBalanceUsd(newUsdBal: number) {
    const coin = depositCoinRef.current;
    const priceUsd = getPriceUsd(coin);
    // Calcular el nativo mediante DELTA para preservar los decimales exactos del servidor.
    // Si hacemos (newUsdBal / priceUsd) completo, el precio fluctuante borra decimales recibidos.
    // En cambio: solo convertimos el cambio (delta) a nativo y lo sumamos al nativo ya guardado.
    const prevUsdBal = ls.getBalance(currentUser);
    const deltaUsd = newUsdBal - prevUsdBal;
    const prevNative = coinBalancesRef.current[coin] ?? 0;
    const newNative = Math.max(0, prevNative + deltaUsd / priceUsd);
    balanceInstantRef.current = true;
    // Actualizar ref de forma síncrona antes del setState para que el nativeSnap sea exacto
    coinBalancesRef.current = { ...coinBalancesRef.current, [coin]: newNative };
    setCoinBalances(prev => ({ ...prev, [coin]: newNative }));

    // Calcular el total USD de TODAS las monedas (la activa con el nuevo valor)
    // Usamos coinBalancesRef.current para evitar closures stale
    const totalUsdSnap = Object.entries({ ...coinBalancesRef.current, [coin]: newNative })
      .reduce((sum, [c, native]) => sum + (native as number) * getPriceUsd(c), 0);

    // Mostrar solo la moneda activa en pantalla — el total va al backend (profiles.balance)
    setBalanceState(newUsdBal);
    ls.setBalance(currentUser, newUsdBal);

    // Sync to Supabase (debounced 800ms to avoid hammering on auto-bet)
    if (balanceSyncTimerRef.current) clearTimeout(balanceSyncTimerRef.current);
    const coinSnap = coin;
    const nativeSnap = newNative;
    const userSnap = currentUser;
    // IMPORTANTE: capturar el estado del guard AHORA, antes de que arranque el timer.
    // Si fetchRemoteBalance no había completado cuando se llamó setCoinBalanceUsd, el sync
    // debe omitirse aunque fetchRemoteBalance complete antes de que el timer dispare.
    // (Evita la race condition: timer creado en t=0, fetchRemoteBalance completa en t=500ms,
    //  timer dispara en t=800ms y borra el balance recién cargado.)
    const remoteLoadedAtCallTime = hasRemoteBalanceLoadedRef.current;
    balanceSyncTimerRef.current = setTimeout(async () => {
      balanceSyncTimerRef.current = null;
      // Omitir si el balance remoto no estaba cargado en el momento de la llamada
      if (!remoteLoadedAtCallTime) return;
      // Marcar sync en vuelo ANTES de las operaciones async para que fetchRemoteBalance
      // no pueda sobreescribir el balance local con el valor stale del servidor mientras
      // getOrRefreshSession o el fetch están en curso.
      balanceSyncInFlightRef.current = true;
      try {
        // Intentar con sesión Supabase fresca primero
        const sess = await getOrRefreshSession();
        if (sess && sess !== supaSessionRef.current) {
          supaSessionRef.current = sess;
          setSupaSession(sess);
        }
        // Usar game-token como fallback (funciona sin Supabase Auth)
        const token = sess?.access_token || localStorage.getItem(`mander_game_token_${userSnap}`);
        if (!token) return;
        // Actualizar cache local con el balance post-apuesta antes de enviar al servidor.
        // Esto evita que el cache quede stale (con el valor pre-apuesta) si fetchRemoteBalance
        // fue bloqueado por el guard de race condition mientras este timer estaba pendiente.
        ls.saveCoinBalances(userSnap, { ...coinBalancesRef.current });
        const syncRes = await fetch("/api/balance/sync", {
          method: "POST",
          headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
          body: JSON.stringify({ currency: coinSnap, balance: nativeSnap, totalUsd: totalUsdSnap }),
        });
        if (syncRes.ok) {
          pendingRakebackRef.current = 0;
          // Si el servidor detecta discrepancia (ej. reset de admin), corregir balance local.
          try {
            const syncData = await syncRes.json();
            if (typeof syncData?.serverBalance === "number") {
              const corrected = syncData.serverBalance;
              const correctedCur = (syncData.currency as string) || coinSnap;
              coinBalancesRef.current = { ...coinBalancesRef.current, [correctedCur]: corrected };
              ls.saveCoinBalances(userSnap, { ...coinBalancesRef.current });
              const newTotalUsd = Object.entries(coinBalancesRef.current)
                .reduce((s, [c, n]) => s + ((n as number) * getPriceUsd(c)), 0);
              updateBalance(newTotalUsd);
              console.log(`[BALANCE SYNC] Corrección del servidor: ${correctedCur}=${corrected}`);
            }
          } catch { /* no JSON body — ok */ }
        }
      } catch {
        // ignorar errores de red; el siguiente bet/sync reintentará
      } finally {
        // Limpiar guard SOLO después de que el sync haya terminado (éxito o error)
        balanceSyncInFlightRef.current = false;
      }
    }, 100);
  }

  // ── Demo-aware balance helpers ────────────────────────────────────────────
  // Returns the active game balance: demo if any, else real.
  function getGameBalance(): number {
    const demo = balanceDemoRef.current;
    return demo > 0 ? demo : ls.getBalance(currentUser);
  }

  // Sets the active game balance. Routes to demo or real based on which is active.
  // Demo wins/losses stay in demo; real wins/losses go to setCoinBalanceUsd.
  function setGameBalance(newVal: number) {
    const demo = balanceDemoRef.current;
    if (demo > 0) {
      const newDemo = Math.max(0, newVal);
      balanceDemoRef.current = newDemo; // update ref immediately for synchronous bet chains
      // Dual protection against false deposit notifications (same as Plinko inline code):
      // 1. advance baseline so demoBalanceEffect sees 0 delta on game credit
      // 2. skip counter as belt-and-suspenders for React batching edge cases
      demoBaselineRef.current = newDemo;
      skipNextDemoNotifRef.current += 1;
      ls.setDemoBalance(currentUser, newDemo);
      setBalanceDemoState(newDemo);
      isDemoBetRef.current = true;
    } else {
      setCoinBalanceUsd(newVal);
      isDemoBetRef.current = false;
    }
  }

  function addBet(amount: number, winAmount: number, game: string = "Casino") {
    ls.addTotalBetsCount(currentUser);
    setTotalBetsCount(ls.getTotalBetsCount(currentUser));
    // Wagering requirement reduction (real-money only, local only — no cash impact)
    const pendingReq = ls.getWagerReq(currentUser);
    if (pendingReq > 0 && !isDemoBetRef.current) ls.setWagerReq(currentUser, Math.max(0, +(pendingReq - amount).toFixed(4)));

    const lw: LiveWin = {
      user: privateMode ? "Anónimo" : currentUser,
      game,
      betUsd: amount,
      win: winAmount > 0,
      profitUsd: winAmount > 0 ? winAmount - amount : -amount,
      createdAt: new Date().toISOString(),
    };
    if (lw.win && lw.profitUsd >= 0.30) {
      setLiveWins(prev => [lw, ...prev].slice(0, 20));
      if ((lw.betUsd + lw.profitUsd) <= 7000) setPinnedBigWins(prev => mergeIntoPinned(prev, lw));
    }

    // ── Bet-result sync: real and demo bets both update wager/rank/rakeback.
    // Demo bets are marked so the server never changes real balance from demo outcomes.
    // No optimistic updates — wager, rank and rakeback only update with server-confirmed values.
    {
      const _token = supaSessionRef.current?.access_token || localStorage.getItem(`mander_game_token_${currentUser}`);
      if (_token) {
        const reqId = (typeof crypto !== "undefined" && crypto.randomUUID ? crypto.randomUUID() : `${Date.now()}-${Math.random().toString(36).slice(2)}`);
        const isDemoBet = isDemoBetRef.current;
        fetch("/api/bet-result", {
          method: "POST",
          headers: { "Content-Type": "application/json", Authorization: `Bearer ${_token}` },
          body: JSON.stringify({ bet_usd: amount, payout_usd: winAmount, game, currency: depositCoinRef.current, is_demo: isDemoBet, request_id: reqId }),
        })
          .then(r => r.ok ? r.json() : null)
          .then((data: any) => {
            if (!data?.stats) return;
            const serverWagered = typeof data.stats.wagered_total === "number" ? data.stats.wagered_total : null;
            if (serverWagered !== null) {
              // Rank-up detection using authoritative server values
              const prevWagered = vipWageredRef.current;
              // Bet-result is the most authoritative source (post-insert re-read from DB view).
              // Still guard: if the re-read somehow returned a pre-bet value, keep the higher estimate.
              const guardedBet = Math.max(prevWagered, serverWagered);
              console.log(`[wager] bet-result → ${serverWagered} (prev ${prevWagered}) → apply ${guardedBet}`);
              const prevRankIdx = getRankIndex(prevWagered);
              const newRankIdx  = getRankIndex(guardedBet);
              setVipWagered(guardedBet);
              vipWageredRef.current = guardedBet;
              if (newRankIdx > prevRankIdx) {
                const existingRaw = localStorage.getItem("rank_pending_reward_" + currentUser);
                let queue: { amount: number; rankName: string; gradient: string; color: string; image: string }[] = [];
                if (existingRaw) { try { const p = JSON.parse(existingRaw); queue = Array.isArray(p) ? p : [p]; } catch {} }
                for (let ri = prevRankIdx + 1; ri <= newRankIdx; ri++) {
                  const rank = VIP_RANKS[ri];
                  const prevRank = VIP_RANKS[ri - 1];
                  if (rank.tier === prevRank.tier) continue;
                  const t = Math.pow(Math.random(), 3);
                  const reward = rank.rewardMin + t * (rank.rewardMax - rank.rewardMin);
                  queue.push({ amount: parseFloat(reward.toFixed(2)), rankName: rank.name, gradient: rank.gradient, color: rank.color, image: rank.image });
                }
                if (queue.length > 0) {
                  localStorage.setItem("rank_pending_reward_" + currentUser, JSON.stringify(queue));
                  setRankPendingReward(queue[0]);
                }
              }
            }
            const rb = data.stats.rakeback;
            if (rb && typeof rb.instant       === "number") setRbInstant(rb.instant);
            if (rb && typeof rb.instant_pending === "number") setRbInstantPending(rb.instant_pending);
            if (rb && typeof rb.instant_accum === "number") setRbInstantAccum(rb.instant_accum);
            if (rb && typeof rb.weekly        === "number") setRbWeekly(rb.weekly);
            if (rb && typeof rb.monthly       === "number") setRbMonthly(rb.monthly);
            // Refresh bet history immediately after the bet is confirmed server-side
            fetchServerBets();
            // Update profileServerStats (Favorite Games, Total Wagered, Best Win, etc.)
            scheduleStatsSync();
            // Notify other open tabs to sync immediately (no-op if no other tabs)
            statsChannelRef.current?.postMessage({ type: "STATS_UPDATED" });
          })
          .catch(() => {
            // Network error — schedule a background sync as fallback
            scheduleStatsSync();
          });
      }
    }
  }

