              <ApuestasSection records={bjBetHistory as ApuestaRecord[]} gameLabel="Blackjack" gameIcon={<img src="/blackjack-thumb.jpg" style={{width:"100%",height:"100%",objectFit:"cover"}} alt="blackjack"/>} fmtMoney={fmtMoney} allGameRecords={allBetRecords} liveBets={mergedLiveBets} rawBets={allUsersBets} topBigWins={serverBigWins} topLuckyBets={serverLuckyBets} lang={lang} coinRates={liveRates} displayInFiat={displayInFiat} fiatSymbol={selectedCurrDef.symbol} fiatRate={effectiveRate} myBets={allBetsForUser}/>
